def investigate(context, acquire):
    receipts = acquire("history")
    actions = context.get("actions", [])
    goal = context.get("goal")

    def run(acts, pm, cm, tr):
        main = {}
        other = {}
        committed = {}
        main_changes = 0
        main_total = 0
        other_total = 0
        in_tx = None
        tx_snapshot = None
        for act in acts:
            op = act.get('op')
            conn = act.get('connection', 'main')
            if op == 'put':
                store = main if conn == 'main' else other
                existed = act.get('key') in store
                if pm == 'ignore':
                    if existed:
                        changed = 0
                    else:
                        store[act.get('key')] = act.get('value')
                        changed = 1
                else:
                    store[act.get('key')] = act.get('value')
                    changed = 1
                if conn == 'main':
                    main_changes = changed
                    main_total += changed
                else:
                    other_total += changed
            elif op == 'update':
                store = main if conn == 'main' else other
                if act.get('key') in store:
                    store[act.get('key')] = act.get('value')
                    changed = 1
                else:
                    changed = 0
                if conn == 'main':
                    main_changes = changed
                    main_total += changed
                else:
                    other_total += changed
            elif op == 'delete':
                store = main if conn == 'main' else other
                if act.get('key') in store:
                    del store[act.get('key')]
                    changed = 1
                else:
                    changed = 0
                if conn == 'main':
                    main_changes = changed
                    main_total += changed
                else:
                    other_total += changed
            elif op == 'begin':
                in_tx = conn
                tx_snapshot = dict(main) if conn == 'main' else dict(other)
            elif op == 'commit':
                if in_tx == 'main':
                    committed = dict(main)
                else:
                    committed = dict(other)
                in_tx = None
            elif op == 'rollback':
                if in_tx == 'main':
                    main = tx_snapshot
                else:
                    other = tx_snapshot
                in_tx = None
        if in_tx is None:
            committed = dict(main)
        if cm == 'changes':
            ch = main_changes
        elif cm == 'total_main':
            ch = main_total
        else:
            ch = main_total + other_total
        return ch, len(committed), sum(committed.values())

    modes = ['ignore', 'replace', 'upsert']
    channels = ['changes', 'total_main', 'total_both']
    triggers = [False, True]

    candidates = []
    for pm in modes:
        for cm in channels:
            for tr in triggers:
                ok = True
                for r in receipts:
                    ra = r.get('actions', [])
                    obs = r.get('observed', {})
                    ch, cc, cs = run(ra, pm, cm, tr)
                    if ch != obs.get('channel') or cc != obs.get('committed_count') or cs != obs.get('committed_sum'):
                        ok = False
                        break
                if ok:
                    candidates.append((pm, cm, tr))

    if not candidates:
        return {"value": None, "unresolved": True}

    results = set()
    for pm, cm, tr in candidates:
        ch, cc, cs = run(actions, pm, cm, tr)
        if goal == 'channel':
            results.add(ch)
        elif goal == 'committed_count':
            results.add(cc)
        elif goal == 'committed_sum':
            results.add(cs)

    if len(results) == 1:
        return {"value": list(results)[0], "unresolved": False}
    return {"value": None, "unresolved": True}

