    def simulate(put_mode, channel_mode, trigger):
        # put_mode: 'ignore', 'replace', 'upsert'
        # channel_mode: 'changes', 'total_main', 'total_both'
        # trigger: bool
        main = {}
        other = {}
        committed = {}
        main_changes = 0
        main_total = 0
        other_total = 0
        in_tx = None
        tx_snapshot = None
        tx_changes = 0
        tx_total = 0
        tx_trigger = 0
        tx_other_total = 0
        tx_other_trigger = 0

        def do_put(conn, key, value):
            nonlocal main_changes, main_total, other_total
            nonlocal tx_changes, tx_total, tx_trigger, tx_other_total, tx_other_trigger
            store = main if conn == 'main' else other
            existed = key in store
            if put_mode == 'ignore':
                if existed:
                    changed = 0
                else:
                    store[key] = value
                    changed = 1
            elif put_mode == 'replace':
                store[key] = value
                changed = 1
            else:
                store[key] = value
                changed = 1
            trig = 1 if (trigger and changed) else 0
            if conn == 'main':
                main_changes = changed
                main_total += changed
                if in_tx == 'main':
                    tx_changes = changed
                    tx_total += changed
                    tx_trigger += trig
            else:
                other_total += changed
                if in_tx == 'other':
                    tx_other_total += changed
                    tx_other_trigger += trig

        def do_update(conn, key, value):
            nonlocal main_changes, main_total, other_total
            nonlocal tx_changes, tx_total, tx_trigger, tx_other_total, tx_other_trigger
            store = main if conn == 'main' else other
            if key in store:
                store[key] = value
                changed = 1
            else:
                changed = 0
            trig = 1 if (trigger and changed) else 0
            if conn == 'main':
                main_changes = changed
                main_total += changed
                if in_tx == 'main':
                    tx_changes = changed
                    tx_total += changed
                    tx_trigger += trig
            else:
                other_total += changed
                if in_tx == 'other':
                    tx_other_total += changed
                    tx_other_trigger += trig

        def do_delete(conn, key):
            nonlocal main_changes, main_total, other_total
            nonlocal tx_changes, tx_total, tx_trigger, tx_other_total, tx_other_trigger
            store = main if conn == 'main' else other
            if key in store:
                del store[key]
                changed = 1
            else:
                changed = 0
            trig = 1 if (trigger and changed) else 0
            if conn == 'main':
                main_changes = changed
                main_total += changed
                if in_tx == 'main':
                    tx_changes = changed
                    tx_total += changed
                    tx_trigger += trig
            else:
                other_total += changed
                if in_tx == 'other':
                    tx_other_total = changed
                    tx_other_trigger += trig

        for act in actions:
            op = act.get('op')
            conn = act.get('connection', 'main')
            if op == 'put':
                do_put(conn, act.get('key'), act.get('value'))
            elif op == 'update':
                do_update(conn, act.get('key'), act.get('value'))
            elif op == 'delete':
                do_delete(conn, act.get('key'))
            elif op == 'begin':
                in_tx = conn
                tx_snapshot = dict(main) if conn == 'main' else dict(other)
                tx_changes = 0
                tx_total = 0
                tx_trigger = 0
                tx_other_total = 0
                tx_other_trigger = 0
            elif op == 'commit':
                if in_tx == 'main':
                    committed = dict(main)
                else:
                    committed = dict(other)
                in_tx = None
            elif op == 'rollback':
                if in_tx == 'main':
                    main = tx_snapshot
                else:
                    other = tx_snapshot
                in_tx = None

        if in_tx is None:
            committed = dict(main)

        if channel_mode == 'changes':
            ch = main_changes
        elif channel_mode == 'total_main':
            ch = main_total
        else:
            ch = main_total + other_total
        return ch, len(committed), sum(committed.values())

